            raise ValueError(f"{name} must be finite")

    if flow < 0:
        raise ValueError("flow must be non-negative")
    if source_level <= 0:
        raise ValueError("source_level must be positive")
    if not 0 < retained_ratio <= 1:
        raise ValueError("retained_ratio must be in (0, 1]")
    if not 0 < transfer_efficiency <= 1:
        raise ValueError("transfer_efficiency must be in (0, 1]")

    remaining = float(source_level * retained_ratio)
    drop = float(source_level - remaining)
    delivered = float(flow * drop / transfer_efficiency)
    return {
        "remaining_level": remaining,
        "usable_drop": drop,
        "delivered_output": delivered,
    }

