import math
import unittest
from fractions import Fraction

from solution import estimate_channel_delivery


class EstimateChannelDeliveryTests(unittest.TestCase):
    def test_defaults(self):
        self.assertEqual(estimate_channel_delivery(), {
            "remaining_level": 350.0,
            "usable_drop": 150.0,
            "delivered_output": 135000.0,
        })

    def test_custom_values_and_float_outputs(self):
        result = estimate_channel_delivery(20, 10, 0.25, 0.5)
        self.assertEqual(result, {"remaining_level": 2.5, "usable_drop": 7.5, "delivered_output": 75.0})
        self.assertTrue(all(type(value) is float for value in result.values()))

    def test_boundaries(self):
        self.assertEqual(estimate_channel_delivery(0, 10, 1, 1), {
            "remaining_level": 10.0,
            "usable_drop": 0.0,
            "delivered_output": 0.0,
        })
        result = estimate_channel_delivery(Fraction(3, 2), Fraction(8, 1), Fraction(1, 2), Fraction(1, 4))
        self.assertEqual(result["delivered_output"], 1.5)
        self.assertTrue(all(type(value) is float for value in result.values()))

    def test_rejects_non_real_and_booleans(self):
        for index in range(4):
            for value in (True, "1", None, 1 + 2j):
                args = [1.0, 2.0, 0.5, 0.5]
                args[index] = value
                with self.subTest(index=index, value=value):
                    with self.assertRaises(TypeError):
                        estimate_channel_delivery(*args)

    def test_rejects_non_finite(self):
        for index in range(4):
            for value in (math.inf, -math.inf, math.nan):
                args = [1.0, 2.0, 0.5, 0.5]
                args[index] = value
                with self.subTest(index=index, value=value):
                    with self.assertRaises(ValueError):
                        estimate_channel_delivery(*args)

    def test_rejects_out_of_range(self):
        invalid = [
            (-1, 2, 0.5, 0.5),
            (1, 0, 0.5, 0.5),
            (1, -1, 0.5, 0.5),
            (1, 2, 0, 0.5),
            (1, 2, -0.1, 0.5),
            (1, 2, 1.01, 0.5),
            (1, 2, 0.5, 0),
            (1, 2, 0.5, 1.01),
        ]
        for args in invalid:
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    estimate_channel_delivery(*args)

    def test_each_call_returns_new_dictionary(self):
        first = estimate_channel_delivery()
        first["remaining_level"] = -1
        self.assertEqual(estimate_channel_delivery()["remaining_level"], 350.0)


if __name__ == "__main__":
    unittest.main()

